cket', 'avatars', 'f48'), ('bucket', 'covers', 'f48'), ('bucket', 'store-builder-images', 'f48'), ('bucket', 'onepage-assets', 'f48'), ('bucket', 'lead-form-files-v2', 'f48'), ('bucket', 'product-videos', 'f48'), ('bucket', 'email-images', 'f48'), ('bucket', 'site-assets', 'f01'), ('bucket', 'site-deployments', 'f01'), ('bucket', 'theme-chat-attachments', 'f104'), ('bucket private', 'digital-products', 'f48'), ('bucket private', 'product-files', 'f48'), ('bucket private', 'digital-assets', 'f48')), res as (select r.kind, r.name, coalesce(f.file, 'not shipped') as fix, case r.kind when 'table' then to_regclass('public.' || r.name) is not null when 'column' then exists (select 1 from pg_attribute a where a.attrelid = to_regclass('public.' || split_part(r.name, '.', 1)) and a.attname = split_part(r.name, '.', 2) and a.attnum > 0 and not a.attisdropped) when 'function' then exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = r.name) when 'index' then to_regclass('public.' || r.name) is not null when 'constraint' then exists (select 1 from pg_constraint k where k.conname = r.name) when 'unique key' then exists (select 1 from pg_index i where i.indrelid = to_regclass('public.' || split_part(r.name, ':', 1)) and i.indisunique and i.indpred is null and (select string_agg(a.attname, ',' order by a.attname) from pg_attribute a where a.attrelid = i.indrelid and a.attnum = any (i.indkey::int2[])) = (select string_agg(x, ',' order by x) from unnest(string_to_array(split_part(r.name, ':', 2), ',')) as x)) when 'bucket' then exists (select 1 from storage.buckets b where b.id = r.name) when 'bucket private' then exists (select 1 from storage.buckets b where b.id = r.name and b.public is not true) when 'policy' then exists (select 1 from pg_policies p where p.schemaname = split_part(r.name, '|', 1) and p.tablename = split_part(r.name, '|', 2) and p.policyname = split_part(r.name, '|', 3)) end as present from req r left join fix f on f.code = r.code), shown as (select kind, case when kind = 'policy' then split_part(name, '|', 2) || ': ' || split_part(name, '|', 3) when kind = 'unique key' then split_part(name, ':', 1) || ' (' || split_part(name, ':', 2) || ')' else name end as name, fix, present from res), finding as (select 'paid files public' as kind, 'bucket ' || b.id || ' is public: its files download without a signed link' as name, 'run-now/16_storage_buckets.sql' as fix from storage.buckets b where b.id in ('digital-products', 'product-files', 'digital-assets') and b.public union all select 'bucket takes anything', 'bucket ' || b.id || ' has no allowed_mime_types: it accepts any file type', 'run-now/16_storage_buckets.sql' from storage.buckets b where b.id in ('product-images', 'avatars', 'covers', 'email-images') and b.allowed_mime_types is null union all select 'anon can reach paid files', 'storage.objects policy ' || p.policyname || ' (' || p.cmd || ') covers a paid file bucket for anon', 'run-now/90_storage_policies_needs_owner.sql (or README Route 1, then 91)' from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and 'anon' = any (p.roles) and (position('digital-products' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) > 0 or position('product-files' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) > 0 or position('digital-assets' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) > 0 or position('bucket_id' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0) union all select 'anyone can write files', 'storage.objects policy ' || p.policyname || ' (' || p.cmd || ') lets any signed in account write with no path check', 'run-now/90_storage_policies_needs_owner.sql (or README Route 1, then 91)' from pg_policies p where p.schemaname = 'storage' and p.tablename = 'objects' and p.cmd in ('INSERT', 'UPDATE', 'DELETE', 'ALL') and 'authenticated' = any (p.roles) and position('storage_owns_path' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0 and position('storage_reserved_upload' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0 and position('auth.uid' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0 and position('owner' in coalesce(p.qual, '') || ' ' || coalesce(p.with_check, '')) = 0 union all select 'open to anon', 'public.' || p.proname || ' can be run with the public key', case when p.proname = 'exec_sql' then 'run-now/20_saved_cards_bounces_and_exec_sql.sql' when p.proname = 'claim_email_flow_jobs' then 'run-now/10_email_automation_functions.sql' when p.proname like 'storage_%' then 'run-now/18_storage_cleanup_functions.sql' else 'run-now/15_upload_functions.sql' end from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('ensure_storage_rls', 'fix_storage_bucket_limit', 'get_creator_storage_usage', 'storage_cleanup_candidates', 'storage_recent_public_images', 'exec_sql', 'claim_email_flow_jobs') and case when exists (select 1 from pg_roles where rolname = 'anon') then has_function_privilege('anon', p.oid, 'execute') else false end union all select 'rls off, policies present', 'public.' || c.relname || ' has ' || (select count(*) from pg_policies q where q.schemaname = 'public' and q.tablename = c.relname) || ' policies but row level security is off', 'alter table public.' || c.relname || ' enable row level security' from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity and exists (select 1 from pg_policies q where q.schemaname = 'public' and q.tablename = c.relname) union all select 'no policies, browser reads it', 'public.' || b.name || ' has row level security and no policies: the app reads it with the public key and will see nothing', 'the file that creates its policies' from (values ('analytics_events'), ('categories'), ('community_posts'), ('course_lessons'), ('course_modules'), ('course_progress'), ('courses'), ('creators'), ('digital_assets'), ('email_campaigns'), ('email_flow_runs'), ('email_flows'), ('email_segments'), ('email_sends'), ('onepages'), ('orders'), ('product_categories'), ('product_variant_files'), ('product_variants'), ('products'), ('profiles'), ('store_builder_configs'), ('subscribers'), ('username_history')) as b(name) join pg_class c on c.oid = to_regclass('public.' || b.name) where c.relrowsecurity and not exists (select 1 from pg_policies q where q.schemaname = 'public' and q.tablename = b.name)), pre as (select 'pre-flight' as kind, x.name, x.fix from (values ('can this role manage storage.objects policies', case when pg_has_role(current_user, (select relowner from pg_class where oid = 'storage.objects'::regclass), 'member') then 'yes' else 'no: part 90 will refuse, use README Route 1' end), ('does this role bypass row level security', case when (select rolbypassrls from pg_roles where rolname = current_user) then 'yes' else 'no: part 16 cannot write bucket settings' end), ('storage.objects names the uploader', case when exists (select 1 from pg_attribute a where a.attrelid = 'storage.objects'::regclass and a.attname = 'owner_id' and not a.attisdropped) then 'owner_id, the policies in 90 and Route 1 are right' else 'owner, Route 1 needs owner = (select auth.uid())' end)) as x(name, fix)), out as (select 0 as ord, (select count(*) filter (where not present) from res)::text || ' missing' as status, 'summary' as kind, (select count(*) from res)::text || ' things the app needs checked, ' || (select count(*) filter (where not present) from res)::text || ' missing, ' || (select count(*) from finding)::text || ' to look at' as name, 'the FIX column names the file to run' as fix union all select 1, 'fact', kind, name, fix from pre union all select 2, 'MISSING', kind, name, fix from shown where not present union all select 3, 'LOOK', kind, name, fix from finding union all select 4, 'ok', kind, count(*) filter (where present)::text || ' of ' || count(*)::text || ' present', '' from shown group by kind union all select 5, 'ok', kind, name, fix from shown where present) select status, kind, name, fix from out order by ord, kind, name;
select policyname, cmd, roles, qual, with_check from pg_policies where schemaname = 'storage' and tablename = 'objects' order by policyname;
